'use client'

import React, { useEffect, useRef, useState } from 'react'
import './designer-scene.css'

// A looping illustration of a designer's day, in a chibi / flat "storyteller" style: a big-headed
// character with bold outlines and flat colours sketches a flow on the whiteboard, has an idea,
// walks to her desk, designs the screen on her laptop, cheers, and walks back.
//
//  - One puppet skeleton (head, torso, two arms, two-part legs). Every joint is a nested <g> that
//    CSS rotates; the timeline lives in designer-scene.css, generated by
//    scripts/gen-designer-scene-css.py. A parent <g transform> only places a joint, because a CSS
//    transform replaces the transform attribute.
//  - Outfit and accents come from the theme (--px-accent), so it fits every theme.
//  - Plays only while on screen. Reduced motion shows one calm frame (seated at the desk).
//  - `freeze` (0..1) pins a moment of the 20s loop, for screenshots and tests.
//  - The board is low so the pen hand can reach every stroke; she works left to right and scoots
//    between strokes (timeline: scripts/gen-designer-scene-css.py).

const OUT = '#2a2347' // outline colour
const SKIN = '#ffe3d1'
const HAIR = '#4a3a86'
const PANTS = '#6a5fb0'
const LOOP_SECONDS = 20

interface Props {
  freeze?: number
  className?: string
  label?: string
}

export function DesignerScene({ freeze, className, label = 'Illustration: a designer sketches a flow on a whiteboard, has an idea, walks to her desk, designs the screen on her laptop and cheers.' }: Props) {
  const ref = useRef<HTMLDivElement>(null)
  const [play, setPlay] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el || freeze !== undefined) return
    const io = new IntersectionObserver(([entry]) => setPlay(entry.isIntersecting), { threshold: 0.2 })
    io.observe(el)
    return () => io.disconnect()
  }, [freeze])

  const frozen = freeze !== undefined
  return (
    <div
      ref={ref}
      className={`sc-root${className ? ` ${className}` : ''}`}
      data-play={frozen ? 'false' : play ? 'true' : 'false'}
      data-frozen={frozen ? 'true' : undefined}
      style={frozen ? ({ '--sc-delay': `${-(freeze as number) * LOOP_SECONDS}s` } as React.CSSProperties) : undefined}
    >
      <svg viewBox="0 0 640 400" role="img" aria-label={label} xmlns="http://www.w3.org/2000/svg">
        <g className="sc-cam">
          <line x1="8" y1="352" x2="632" y2="352" stroke="var(--sc-floor)" strokeWidth="3" strokeLinecap="round" />
          <Whiteboard />
          <Desk />
          <Character />
          <Sparkles />
          <Confetti />
        </g>
      </svg>
    </div>
  )
}

/* ── The room ──────────────────────────────────────────────────────────── */

