function Sparkles() {
  const star = 'M0 -9 L2.4 -2.4 L9 0 L2.4 2.4 L0 9 L-2.4 2.4 L-9 0 L-2.4 -2.4 Z'
  return (
    <g className="sc-sparkles" fill="#ffd34d" stroke={OUT} strokeWidth="1.2" strokeLinejoin="round">
      <g transform="translate(604 160)"><path className="sc-sp1" d={star} /></g>
      <g transform="translate(466 158) scale(.8)"><path className="sc-sp2" d={star} /></g>
      <g transform="translate(614 206) scale(.65)"><path className="sc-sp3" d={star} /></g>
      <g transform="translate(372 150) scale(.7)"><path className="sc-sp2" d={star} /></g>
    </g>
  )
}

const CONFETTI = ['#e53416', '#ffd34d', '#3fc1c9', '#ff9fb4', '#ffd34d', '#e53416', '#3fc1c9', '#ff9fb4']
function Confetti() {
  return (
    <g stroke={OUT} strokeWidth="1.4">
      {CONFETTI.map((c, i) => (
        <g key={i} transform="translate(534 176)">
          {i % 2 ? <rect className={`sc-cf${i}`} x="-4" y="-2.5" width="8" height="5" rx="1" fill={c} /> : <circle className={`sc-cf${i}`} r="3.4" fill={c} />}
        </g>
      ))}
    </g>
  )
}

/* ── The character: chibi proportions (head about twice the width of the body) ── */

/** An outlined stub: outline pass then fill pass. `from` lets a lower segment start inside the joint above it. */
function Stub({ len, w, color, from = 0 }: { len: number; w: number; color: string; from?: number }) {
  return (
    <g strokeLinecap="round">
      <line x1="0" y1={from + (from ? 3 : 0)} x2="0" y2={len} stroke={OUT} strokeWidth={w + 6.5} />
      <line x1="0" y1={from} x2="0" y2={len} stroke={color} strokeWidth={w} />
    </g>
  )
}

function Leg({ x, side }: { x: number; side: 'L' | 'R' }) {
  return (
    <g transform={`translate(${x} -60)`}>
      <g className={`j-hip${side}`}>
        <Stub len={28} w={10} color={PANTS} />
        <g transform="translate(0 28)">
          <g className={`j-knee${side}`}>
            <Stub len={26} w={10} color={PANTS} from={-4} />
            <g transform="translate(0 29)">
              <ellipse cx="5" cy="0" rx="13" ry="8" fill="#fff" stroke={OUT} strokeWidth="3" />
              <ellipse cx="11" cy="1" rx="6" ry="5" fill="var(--px-accent)" />
            </g>
          </g>
        </g>
      </g>
    </g>
  )
}

function Arm({ x, side }: { x: number; side: 'L' | 'R' }) {
  return (
    <g transform={`translate(${x} -40)`}>
      <g className={`j-sh${side}`}>
        <Stub len={34} w={10.5} color="var(--sc-outfit)" />
        <circle cx="0" cy="38" r="8" fill={SKIN} stroke={OUT} strokeWidth="3" />
        {side === 'L' && (
          <g className="f-marker"><rect x="-2.5" y="40" width="5" height="14" rx="2" fill="var(--px-accent)" stroke={OUT} strokeWidth="1.6" /></g>
        )}
      </g>
    </g>
  )
}

function Face() {
  return (
    <g>
      <g className="j-look">
        {/* open eyes */}
        <g className="f-normal"><g className="f-blink">
          {[-17, 17].map(x => (
            <g key={x} transform={`translate(${x} -38)`}>
              <ellipse rx="8.5" ry="11" fill={OUT} />
              <ellipse cx="0" cy="5" rx="5" ry="3.6" fill="#3fc1c9" />
              <circle cx="-2.6" cy="-3.8" r="3.4" fill="#fff" />
              <circle cx="3" cy="3" r="1.6" fill="#fff" />
            </g>
          ))}
        </g></g>
        {/* happy eyes (^ ^) for the cheer */}
        <path className="f-happy" d="M-26 -36 q9 -11 18 0 M8 -36 q9 -11 18 0" fill="none" stroke={OUT} strokeWidth="3.4" strokeLinecap="round" />
      </g>
      <path d="M-26 -55 q8 -4 16 -1 M10 -56 q8 -3 16 1" fill="none" stroke={OUT} strokeWidth="2.4" strokeLinecap="round" />
      <ellipse cx="-30" cy="-26" rx="7" ry="4" fill="#ff9fb4" opacity=".7" />
      <ellipse cx="30" cy="-26" rx="7" ry="4" fill="#ff9fb4" opacity=".7" />
      <path d="M-4 -24 q4 5 8 0" fill="none" stroke={OUT} strokeWidth="2.4" strokeLinecap="round" />
      <ellipse className="f-mouth" cx="0" cy="-21" rx="5.5" ry="6.5" fill="#c2415e" stroke={OUT} strokeWidth="2.4" />
    </g>
  )
}

function Head() {
  return (
    <g transform="translate(0 -50)">
      <g className="j-head">
        {/* pigtails hang behind the head and lag the body */}
        <g transform="translate(-42 -40)"><g className="j-pigL"><ellipse cx="0" cy="18" rx="11" ry="19" fill={HAIR} stroke={OUT} strokeWidth="3.2" /></g></g>
        <g transform="translate(42 -40)"><g className="j-pigR"><ellipse cx="0" cy="18" rx="11" ry="19" fill={HAIR} stroke={OUT} strokeWidth="3.2" /></g></g>
        <ellipse cx="0" cy="-46" rx="49" ry="45" fill={HAIR} stroke={OUT} strokeWidth="3.5" />
        <ellipse cx="0" cy="-40" rx="44" ry="37" fill={SKIN} stroke={OUT} strokeWidth="3.5" />
        <Face />
        {/* fringe */}
        <path d="M-45 -46 C-47 -80 -22 -90 0 -90 C22 -90 47 -80 45 -46 C38 -60 29 -62 21 -54 C15 -63 6 -64 0 -54 C-6 -64 -15 -63 -21 -54 C-29 -62 -38 -60 -45 -46 Z" fill={HAIR} stroke={OUT} strokeWidth="3.5" strokeLinejoin="round" />
        <path d="M-45 -46 C-47 -26 -42 -14 -38 -8 L-31 -22 C-34 -30 -36 -38 -36 -46 Z M45 -46 C47 -26 42 -14 38 -8 L31 -22 C34 -30 36 -38 36 -46 Z" fill={HAIR} stroke={OUT} strokeWidth="2.6" strokeLinejoin="round" />
        {/* hair clip */}
        <path d="M-33 -72 l3 -7 l3 7 l7 3 l-7 3 l-3 7 l-3 -7 l-7 -3 z" fill="var(--px-accent)" stroke={OUT} strokeWidth="2" strokeLinejoin="round" />
      </g>
    </g>
  )
}

function Torso() {
  return (
    <g transform="translate(0 -60)">
      <g className="j-torso">
        <rect x="-20" y="-52" width="40" height="52" rx="14" fill="var(--sc-outfit)" stroke={OUT} strokeWidth="3.5" />
        <path d="M-12 -48 q12 10 24 0" fill="none" stroke={OUT} strokeWidth="2.4" strokeLinecap="round" />
        <path d="M-12 -14 h24" fill="none" stroke={OUT} strokeWidth="2.2" strokeLinecap="round" opacity=".55" />
        <Head />
        <Arm x={-21} side="L" />
        <Arm x={21} side="R" />
      </g>
    </g>
  )
}

function Character() {
  return (
    <g transform="translate(0 352)">
      <g className="r-x">
        <g transform="scale(1.2)">
          <ellipse cx="0" cy="0" rx="34" ry="5" fill="var(--sc-shadow)" />
          <g className="r-bob">
            <Leg x={-10} side="L" />
            <Leg x={10} side="R" />
            <Torso />
          </g>
        </g>
        {/* the "!" that pops when she has the idea */}
        <g transform="translate(46 -262)">
          <g className="sc-bubble">
            <circle cx="0" cy="0" r="16" fill="#ffd34d" stroke={OUT} strokeWidth="3" />
            <path d="M0 -8 v8" stroke={OUT} strokeWidth="3.4" strokeLinecap="round" />
            <circle cx="0" cy="7.5" r="2.1" fill={OUT} />
          </g>
        </g>
      </g>
    </g>
  )
}
